// ============================================================
// Monta o payload para o ComfyUI no RunPod.
// IMPORTANTE: substitua o objeto `workflow` abaixo pelo SEU
// workflow exportado do ComfyUI (menu > Save (API Format)).
// O exemplo gera imagens; para vídeo use AnimateDiff/SVD/Veo
// no seu workflow e mantenha os mesmos pontos de injeção.
// ============================================================
const job = $input.first().json.body;

const prompt = [
  job.prompt || '',
  `Produto: ${job.product}`,
  `Estilo: ${job.style}, duração alvo ${job.duration}s`,
  'vertical 9:16, alta qualidade, iluminação cinematográfica'
].filter(Boolean).join(', ');

// >>> COLE AQUI o seu workflow ComfyUI (formato API) <<<
const workflow = {
  '3': { class_type: 'KSampler', inputs: { seed: Math.floor(Math.random()*1e15), steps: 20, cfg: 7, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['4',0], positive: ['6',0], negative: ['7',0], latent_image: ['5',0] } },
  '4': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: 'SEU_MODELO.safetensors' } },
  '5': { class_type: 'EmptyLatentImage', inputs: { width: 768, height: 1344, batch_size: 1 } },
  '6': { class_type: 'CLIPTextEncode', inputs: { text: prompt, clip: ['4',1] } },
  '7': { class_type: 'CLIPTextEncode', inputs: { text: 'texto, marca d\'água, baixa qualidade, borrado', clip: ['4',1] } },
  '8': { class_type: 'VAEDecode', inputs: { samples: ['3',0], vae: ['4',2] } },
  '9': { class_type: 'SaveImage', inputs: { filename_prefix: `mineraai/${job.job_id}`, images: ['8',0] } }
};

return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, input: { workflow } } }];

// Extrai a URL do arquivo gerado (vídeo ou imagem) da resposta do RunPod.
const r = $input.first().json;
const out = r.output;
let url = '';
if (typeof out === 'string') url = out;
else if (Array.isArray(out)) url = out.find(x => typeof x === 'string') || '';
else if (out && typeof out === 'object') {
  url = out.video_url || out.url || JSON.stringify(out);
}
const job = $('Montar Workflow ComfyUI').first().json;
return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, video_url: url, cost_usd: r.cost || null } }];
